param([string]$Mode='after',[string]$EditorPath='D:\Unity\Lib\6000.6.4f1\Editor\Unity.exe')
$ErrorActionPreference='Stop';$repo=Split-Path $PSScriptRoot -Parent;$stage=Join-Path $repo 'build/phone-test-r24/stage/unity';$output=Join-Path $repo 'build/feedback-1114-r39'
$directory=Get-Content -LiteralPath (Join-Path $repo 'unity/Assets/Resources/Majsoul/WardrobeDirectory/packs-windows.json') -Raw | ConvertFrom-Json
$packs=@{};foreach($pack in $directory.packs){$packs[$pack.key]=$pack};$wanted=[Collections.Generic.HashSet[string]]::new()
function IncludePack([string]$key){if($wanted.Add($key)){foreach($dep in $packs[$key].dependencies){IncludePack $dep}}}
IncludePack (($directory.items | Where-Object id -eq 'effect_liqi_25hf').pack)
$files=@(& rg --files (Join-Path $repo 'build') -g '*.bundle');$index=@{};foreach($name in $files){$base=[IO.Path]::GetFileName($name);$index[$base]=@($index[$base])+@($name)}
foreach($key in $wanted){$pack=$packs[$key];if($pack.builtin){continue};$source=$null;foreach($file in @($index[$pack.file])+@($index[$pack.sha256+'.bundle'])){if($file -and (Get-Item -LiteralPath $file).Length -eq $pack.bytes -and (Get-FileHash -LiteralPath $file).Hash.ToLowerInvariant() -eq $pack.sha256){$source=$file;break}};if(-not $source){throw "Missing verified test pack: $key"};$folder=Join-Path $output ('wardrobes/'+$key);New-Item -ItemType Directory -Path $folder -Force | Out-Null;$target=Join-Path $folder ($pack.sha256+'.bundle');if(-not (Test-Path -LiteralPath $target)){New-Item -ItemType HardLink -Path $target -Target $source | Out-Null};[IO.File]::WriteAllText($target+'.ok',$pack.sha256)}
Copy-Item -LiteralPath (Join-Path $repo 'tests/Feedback1114Review.cs') -Destination (Join-Path $stage 'Assets/Editor/Feedback1114Review.cs') -Force
foreach($name in @('NativeWinningTileQueue.cs','NativeWinPlayback.cs','MatchIntroduction.cs')){Copy-Item -LiteralPath (Join-Path $repo ($(if($Mode -eq 'before'){'build/feedback-1114-r39/baseline-scripts/'}else{'unity/Assets/Scripts/'})+$name)) -Destination (Join-Path $stage ('Assets/Scripts/'+$name)) -Force}
$prior=$env:YUNJIAN_1114_REPO;$priorMode=$env:YUNJIAN_1114_MODE
foreach($name in @('failed.txt','report.json')){Remove-Item -LiteralPath (Join-Path $output ($Mode+'/'+$name)) -ErrorAction SilentlyContinue}
try{$env:YUNJIAN_1114_REPO=$repo;$env:YUNJIAN_1114_MODE=$Mode;$args='-batchmode -projectPath "{0}" -executeMethod YunJian.Riichi.Editor.Feedback1114Review.Run -logFile "{1}"' -f $stage,(Join-Path $output ($Mode+'.log'));$p=Start-Process -FilePath $EditorPath -ArgumentList $args -WindowStyle Hidden -PassThru;$p.Id | Set-Content (Join-Path $output ($Mode+'.pid'));$end=[DateTime]::UtcNow.AddMinutes(5);while(-not $p.WaitForExit(1000)){if([DateTime]::UtcNow -ge $end){throw '1114 review timed out'}};if($p.ExitCode -ne 0){throw '1114 review failed; inspect its failed.txt'};Get-Content (Join-Path $output ($Mode+'/report.json')) -Raw | ConvertFrom-Json | Select-Object mode,checks,androidDeviceTested}finally{$env:YUNJIAN_1114_REPO=$prior;$env:YUNJIAN_1114_MODE=$priorMode}
